from __future__ import annotations

import logging
import pandas as pd
import torch
import numpy as np
from pathlib import Path
from typing import Any, Callable

from torch.utils.data import Dataset
from torch.nn.utils.rnn import pad_sequence
from .tokenizer import Tokenizer

logger = logging.getLogger(__name__)

class ManifestDataset(Dataset):
    """Dataset that loads individual .pt files generated by the caching script.
    
    Reads the `trials.csv` manifest and dynamically loads tensors at runtime.
    Crops or pads each trial to a fixed number of time samples so that
    PyTorch can batch them.
    """
    
    def __init__(
        self,
        manifest_path: str | Path,
        dataset_name: str,
        split: str = "train",
        subjects: list[str] | None = None,
        transform: Callable | None = None,
        tokenizer: Tokenizer | None = None,
        max_samples: int = 500,
    ):
        self.manifest_path = Path(manifest_path)
        self.dataset_name = dataset_name
        self.split = split
        self.transform = transform
        self.tokenizer = tokenizer
        self.max_samples = max_samples
        
        # Load the manifest
        df = pd.read_csv(manifest_path)
        
        # Filter by dataset
        df = df[df["dataset"] == dataset_name]
        
        # Filter by split (if split column exists)
        if "split" in df.columns:
            df = df[df["split"] == split]
            
        # Filter by subjects
        if subjects is not None:
            df = df[df["subject_id"].isin(subjects)]
            
        # Drop rows where caching failed or cache_path is null
        if "cache_path" in df.columns:
            df = df.dropna(subset=["cache_path"])
        
        self.df = df.reset_index(drop=True)
        
        # Resolve label column: prefer "label", fall back to "trial_type", then "task"
        self._label_col = None
        for col_candidate in ["label", "trial_type", "task"]:
            if col_candidate in self.df.columns:
                self._label_col = col_candidate
                break
        
        # Build a label map dynamically
        self.label_str_to_int = {}
        self.label_int_to_str = {}
        if self._label_col is not None:
            unique_labels = sorted([str(x) for x in self.df[self._label_col].dropna().unique()])
            for i, lab in enumerate(unique_labels):
                self.label_str_to_int[lab] = i
                self.label_int_to_str[i] = lab
        
        logger.info(
            f"ManifestDataset({dataset_name}): {len(self.df)} trials, "
            f"{self.n_classes} classes (label_col='{self._label_col}'), "
            f"max_samples={max_samples}"
        )

    def __len__(self) -> int:
        return len(self.df)

    def _crop_or_pad(self, eeg: torch.Tensor) -> torch.Tensor:
        """Crop or pad tensor to self.max_samples along the time axis.
        
        eeg shape: (C, T)
        - If T > max_samples: random crop during train, center crop otherwise.
        - If T < max_samples: zero-pad at the end.
        """
        C, T = eeg.shape
        target = self.max_samples
        
        if T > target:
            if self.split == "train":
                start = torch.randint(0, T - target, (1,)).item()
            else:
                start = (T - target) // 2
            eeg = eeg[:, start : start + target]
        elif T < target:
            pad = torch.zeros(C, target - T, dtype=eeg.dtype)
            eeg = torch.cat([eeg, pad], dim=1)
        
        return eeg

    def __getitem__(self, idx: int) -> dict[str, Any]:
        row = self.df.iloc[idx]
        
        # Load the PyTorch tensor (C, T)
        # The caching script saves to: data/processed/common_250hz/<dataset>/<trial_id>.pt
        if "cache_path" in row.index and pd.notnull(row.get("cache_path")):
            cache_path = Path(row["cache_path"])
        else:
            # Resolve from manifest location: manifest is at data/processed/manifests/trials.csv
            # cache is at data/processed/common_250hz/<dataset>/<trial_id>.pt
            data_processed_dir = self.manifest_path.parent.parent  # data/processed/
            cache_path = (
                data_processed_dir / "common_250hz"
                / self.dataset_name / f"{row['trial_id']}.pt"
            )
        
        if not cache_path.exists():
            raise FileNotFoundError(f"Cached tensor not found: {cache_path}")
            
        eeg = torch.load(cache_path, weights_only=True)
        
        # eeg is expected to be a tensor. If it's a dict, extract the tensor.
        if isinstance(eeg, dict) and "tensor" in eeg:
            eeg = eeg["tensor"]
            
        # Ensure dtype and crop/pad to fixed length
        eeg = eeg.float()
        eeg = self._crop_or_pad(eeg)
        
        if self.transform is not None:
            eeg = self.transform(eeg)
            
        # Process label
        label_val = 0
        if self._label_col is not None and self._label_col in row.index:
            raw_lab = str(row[self._label_col])
            label_val = self.label_str_to_int.get(raw_lab, 0)
            
        # Process text and tokenize
        text = str(row.get("text", ""))
        target_tokens = torch.empty(0, dtype=torch.long)
        target_length = 0
        
        if self.tokenizer is not None and text:
            # We add EOS but usually do NOT feed SOS as target.
            # In standard setup: Target is [token1, token2, EOS]
            ids = self.tokenizer.encode(text, add_special_tokens=False)
            ids.append(self.tokenizer.EOS_ID)
            target_tokens = torch.tensor(ids, dtype=torch.long)
            target_length = len(ids)
            
        sample = {
            "eeg": eeg,
            "label": torch.tensor(label_val, dtype=torch.long),
            "text": text,
            "target_tokens": target_tokens,
            "target_length": torch.tensor(target_length, dtype=torch.long),
            "dataset": self.dataset_name,
            "subject_id": str(row.get("subject_id", "unknown")),
            "trial_id": str(row.get("trial_id", f"trial_{idx}")),
        }
        
        return sample

    @property
    def n_classes(self) -> int:
        return max(1, len(self.label_str_to_int))

    def get_class_weights(self) -> torch.Tensor:
        if self._label_col is None or self._label_col not in self.df.columns:
            return torch.ones(self.n_classes)
            
        counts = self.df[self._label_col].value_counts()
        total = len(self.df)
        weights = torch.zeros(self.n_classes)
        for raw_lab, count in counts.items():
            lab_idx = self.label_str_to_int[str(raw_lab)]
            weights[lab_idx] = total / (self.n_classes * count)
        return weights


def collate_fn(batch: list[dict]) -> dict:
    """Custom collate to pad target_tokens correctly."""
    collated = {
        "eeg": torch.stack([item["eeg"] for item in batch]),
        "label": torch.stack([item["label"] for item in batch]),
        "text": [item["text"] for item in batch],
        "dataset": [item["dataset"] for item in batch],
        "subject_id": [item["subject_id"] for item in batch],
        "trial_id": [item["trial_id"] for item in batch],
    }
    
    lengths = [item["target_length"].item() for item in batch]
    collated["target_length"] = torch.tensor(lengths, dtype=torch.long)
    
    # Pad tokens
    if sum(lengths) > 0:
        tokens = [item["target_tokens"] for item in batch]
        collated["target_tokens"] = pad_sequence(tokens, batch_first=True, padding_value=0)
    else:
        collated["target_tokens"] = torch.empty((len(batch), 0), dtype=torch.long)
        
    return collated
